const items = $input.all().map(x => x.json).filter(r => r.item_id && r.title);
if (items.length < 2) {
  return [{ json: { skip: true, reason: 'too_few_items', count: items.length } }];
}
const catalog = items.map((r, i) => `${i}. [${r.item_type}#${r.item_id}] ${String(r.title).slice(0,120)}`).join('\n');
const allowedIds = items.map(r => `${r.item_type}:${r.item_id}`);
const prompt = `아래는 최근 운영 기록 항목 목록이다. 서로 명확히 관련된 항목 쌍만 골라라 — 같은 주제, 같은 사업 아이디어, 하나가 다른 하나의 근거나 결과인 경우만 인정한다. 제목만 보고 억지로 추측하지 말고, 관련이 불확실하면 포함하지 마라. 최대 10쌍만 골라라.\n\n목록:\n${catalog}\n\n각 항목은 번호로 표시했다. 출력은 JSON 배열만 반환하고 다른 텍스트는 쓰지 마라. 각 원소는 {"from":번호,"to":번호,"relation":"same_topic|based_on|led_to","reason":"15자 이내 한국어 이유"} 형식이다. 관련 쌍이 없으면 빈 배열 []을 반환하라.`;
const body = { model: 'qwen3.5:4b', stream: false, think: false, options: { num_predict: 500, temperature: 0.1 }, messages: [ { role: 'system', content: '당신은 Atemoya 운영 기록 사이의 실제 관련성만 찾는 편집자다. 확실하지 않은 관련성은 절대 만들어내지 않는다. JSON 배열 외의 텍스트는 출력하지 않는다.' }, { role: 'user', content: prompt } ] };
return [{ json: { skip: false, items, allowedIds, ollama_body: JSON.stringify(body) } }];

const prev = $('관련성 프롬프트 구성').first().json;
if (prev.skip) return [{ json: { rows: [] } }];
const items = prev.items;
const allowed = new Set(prev.allowedIds);
let text = '';
try { text = $json.message.content; } catch (e) { text = ''; }
const match = text.match(/\[[\s\S]*\]/);
let parsed = [];
try { parsed = match ? JSON.parse(match[0]) : []; } catch (e) { parsed = []; }
const rows = [];
for (const p of parsed.slice(0, 10)) {
  const a = items[p.from]; const b = items[p.to];
  if (!a || !b) continue;
  const fromKey = `${a.item_type}:${a.item_id}`; const toKey = `${b.item_type}:${b.item_id}`;
  if (!allowed.has(fromKey) || !allowed.has(toKey) || fromKey === toKey) continue;
  const relation = ['same_topic','based_on','led_to'].includes(p.relation) ? p.relation : 'same_topic';
  const reason = String(p.reason || '').slice(0, 80);
  if (!reason) continue;
  rows.push({ from_type: a.item_type, from_id: a.item_id, to_type: b.item_type, to_id: b.item_id, relation, reason });
}
return rows.map(r => ({ json: r }));
